    React.createElement('line', { x1: 8, y1: 2.5, x2: 8, y2: 13.5, stroke: 'currentColor', strokeWidth: 1.1 }),
    React.createElement('line', { x1: 1.5, y1: 8, x2: 14.5, y1: 8, stroke: 'currentColor', strokeWidth: 1.1 })
